        .unwrap_err()
        .to_string();
        assert!(error.contains(if field == "row" {
            "pinned fixture provenance"
        } else {
            "SHA-256 mismatch"
        }));
        assert_eq!(std::fs::read(&output).unwrap(), b"keep-me");
        assert_eq!(std::fs::read_dir(directory.path()).unwrap().count(), 1);
    }
